"""Document Generation Tools for PDF, DOCX, TXT, and Excel."""

import os
from pathlib import Path
from typing import Any, Dict, List, Optional
from pydantic import BaseModel, Field
from app.core.logging import get_logger
from app.core.security import PathSecurity, sanitize_filename
from app.tools.base import BaseTool, RiskLevel, ToolResult

logger = get_logger("origin.tools.document")


def _record_file_in_db(
    filename: str,
    file_path: Path,
    file_type: str,
    mime_type: str,
    context: Optional[Dict[str, Any]],
) -> Optional[str]:
    """Helper to persist generated file record in database."""
    if not context or "db" not in context:
        return None

    try:
        from app.db.models.file import GeneratedFile

        db = context["db"]
        task_id = context.get("task_id")
        file_size = PathSecurity.validate_file_size(file_path)
        file_hash = PathSecurity.compute_sha256(file_path)

        file_rec = GeneratedFile(
            task_id=task_id,
            filename=filename,
            file_path=str(file_path.relative_to(PathSecurity.get_workspace_root())),
            file_type=file_type,
            file_size_bytes=file_size,
            mime_type=mime_type,
            file_hash=file_hash,
        )
        db.add(file_rec)
        db.commit()
        db.refresh(file_rec)
        return file_rec.id
    except Exception as exc:
        logger.warning(f"Could not record file in database: {exc}")
        return None


# --- 1. PDF Generation Tool ---

class PDFSection(BaseModel):
    heading: str
    content: str


class CreatePDFInput(BaseModel):
    title: str = Field(description="Document title")
    sections: List[PDFSection] = Field(description="List of report sections with heading and content")
    filename: Optional[str] = Field(default=None, description="Target PDF filename (e.g. report.pdf)")
    author: Optional[str] = Field(default="ORIGIN AI Operator", description="Author or organization name")


class CreatePDFTool(BaseTool):
    tool_id = "create_pdf"
    name = "Create PDF Document"
    description = "Generates a styled, publication-grade PDF report with title, headers, and paragraphs."
    input_schema = CreatePDFInput
    risk_level = RiskLevel.LOW_RISK
    timeout_seconds = 30

    async def run(self, input_params: CreatePDFInput, context: Optional[Dict[str, Any]] = None) -> ToolResult:
        try:
            from reportlab.lib import colors
            from reportlab.lib.pagesizes import letter
            from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
            from reportlab.platypus import Paragraph, SimpleDocTemplate, Spacer, HRFlowable

            base_name = input_params.filename or f"{input_params.title.lower().replace(' ', '_')[:32]}.pdf"
            if not base_name.endswith(".pdf"):
                base_name += ".pdf"

            safe_name = sanitize_filename(base_name)
            target_path = PathSecurity.resolve_safe_path(safe_name)

            doc = SimpleDocTemplate(
                str(target_path),
                pagesize=letter,
                rightMargin=54,
                leftMargin=54,
                topMargin=54,
                bottomMargin=54,
            )

            styles = getSampleStyleSheet()
            title_style = ParagraphStyle(
                "DocTitle",
                parent=styles["Heading1"],
                fontName="Helvetica-Bold",
                fontSize=24,
                leading=28,
                textColor=colors.HexColor("#1A365D"),
                spaceAfter=10,
            )
            subtitle_style = ParagraphStyle(
                "DocSubtitle",
                parent=styles["Normal"],
                fontName="Helvetica-Oblique",
                fontSize=11,
                leading=14,
                textColor=colors.HexColor("#4A5568"),
                spaceAfter=15,
            )
            h2_style = ParagraphStyle(
                "DocH2",
                parent=styles["Heading2"],
                fontName="Helvetica-Bold",
                fontSize=14,
                leading=18,
                textColor=colors.HexColor("#2B6CB0"),
                spaceBefore=14,
                spaceAfter=6,
            )
            body_style = ParagraphStyle(
                "DocBody",
                parent=styles["Normal"],
                fontName="Helvetica",
                fontSize=10,
                leading=15,
                textColor=colors.HexColor("#2D3748"),
                spaceAfter=10,
            )

            story = [
                Paragraph(input_params.title, title_style),
                Paragraph(f"Generated by {input_params.author}", subtitle_style),
                HRFlowable(width="100%", thickness=1.5, color=colors.HexColor("#CBD5E0"), spaceAfter=15),
            ]

            for sec in input_params.sections:
                story.append(Paragraph(sec.heading, h2_style))
                paragraphs = sec.content.split("\n\n")
                for p in paragraphs:
                    if p.strip():
                        story.append(Paragraph(p.strip().replace("\n", "<br/>"), body_style))
                story.append(Spacer(1, 8))

            doc.build(story)

            size_bytes = PathSecurity.validate_file_size(target_path)
            file_hash = PathSecurity.compute_sha256(target_path)
            file_id = _record_file_in_db(safe_name, target_path, "pdf", "application/pdf", context)

            return ToolResult(
                success=True,
                data={
                    "filename": safe_name,
                    "file_path": str(target_path),
                    "file_size_bytes": size_bytes,
                    "sha256": file_hash,
                    "file_id": file_id,
                },
                metadata={"file_type": "pdf", "file_id": file_id},
            )
        except Exception as exc:
            logger.error(f"Failed to generate PDF: {exc}")
            return ToolResult(success=False, error=f"PDF Generation failed: {str(exc)}")


# --- 2. DOCX Generation Tool ---

class DOCXSection(BaseModel):
    heading: str
    content: str


class CreateDOCXInput(BaseModel):
    title: str = Field(description="Document title")
    sections: List[DOCXSection] = Field(description="Sections with heading and content")
    filename: Optional[str] = Field(default=None, description="Target DOCX filename (e.g. report.docx)")
    subtitle: Optional[str] = Field(default=None, description="Optional document subtitle")


class CreateDOCXTool(BaseTool):
    tool_id = "create_docx"
    name = "Create DOCX Document"
    description = "Generates a structured Microsoft Word (.docx) report with styled headings, paragraphs, and metadata."
    input_schema = CreateDOCXInput
    risk_level = RiskLevel.LOW_RISK
    timeout_seconds = 30

    async def run(self, input_params: CreateDOCXInput, context: Optional[Dict[str, Any]] = None) -> ToolResult:
        try:
            import docx
            from docx.shared import Inches, Pt, RGBColor

            base_name = input_params.filename or f"{input_params.title.lower().replace(' ', '_')[:32]}.docx"
            if not base_name.endswith(".docx"):
                base_name += ".docx"

            safe_name = sanitize_filename(base_name)
            target_path = PathSecurity.resolve_safe_path(safe_name)

            doc = docx.Document()

            # Set standard margins
            for section in doc.sections:
                section.top_margin = Inches(1)
                section.bottom_margin = Inches(1)
                section.left_margin = Inches(1)
                section.right_margin = Inches(1)

            # Document Title
            title_p = doc.add_paragraph()
            title_run = title_p.add_run(input_params.title)
            title_run.font.name = "Calibri"
            title_run.font.size = Pt(24)
            title_run.font.bold = True
            title_run.font.color.rgb = RGBColor(0x1A, 0x36, 0x5D)

            if input_params.subtitle:
                sub_p = doc.add_paragraph()
                sub_run = sub_p.add_run(input_params.subtitle)
                sub_run.font.name = "Calibri"
                sub_run.font.size = Pt(12)
                sub_run.font.italic = True
                sub_run.font.color.rgb = RGBColor(0x71, 0x80, 0x96)

            doc.add_paragraph()  # Spacer

            for sec in input_params.sections:
                h = doc.add_heading(sec.heading, level=1)
                h.style.font.color.rgb = RGBColor(0x2B, 0x6C, 0xB0)

                paragraphs = sec.content.split("\n\n")
                for p_text in paragraphs:
                    trimmed = p_text.strip()
                    if trimmed.startswith("- ") or trimmed.startswith("* "):
                        bullet_p = doc.add_paragraph(style="List Bullet")
                        bullet_p.add_run(trimmed[2:])
                    elif trimmed:
                        doc.add_paragraph(trimmed)

            doc.save(str(target_path))

            size_bytes = PathSecurity.validate_file_size(target_path)
            file_hash = PathSecurity.compute_sha256(target_path)
            file_id = _record_file_in_db(
                safe_name,
                target_path,
                "docx",
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                context,
            )

            return ToolResult(
                success=True,
                data={
                    "filename": safe_name,
                    "file_path": str(target_path),
                    "file_size_bytes": size_bytes,
                    "sha256": file_hash,
                    "file_id": file_id,
                },
                metadata={"file_type": "docx", "file_id": file_id},
            )
        except Exception as exc:
            logger.error(f"Failed to generate DOCX: {exc}")
            return ToolResult(success=False, error=f"DOCX Generation failed: {str(exc)}")


# --- 3. TXT Generation Tool ---

class CreateTXTInput(BaseModel):
    filename: str = Field(description="Target text filename (e.g. summary.txt)")
    content: str = Field(description="Raw text content to write")


class CreateTXTTool(BaseTool):
    tool_id = "create_txt"
    name = "Create Text File"
    description = "Creates a plain text file (.txt) safely in the authorized workspace."
    input_schema = CreateTXTInput
    risk_level = RiskLevel.LOW_RISK
    timeout_seconds = 15

    async def run(self, input_params: CreateTXTInput, context: Optional[Dict[str, Any]] = None) -> ToolResult:
        try:
            base_name = input_params.filename
            if not base_name.endswith(".txt"):
                base_name += ".txt"

            safe_name = sanitize_filename(base_name)
            target_path = PathSecurity.resolve_safe_path(safe_name)

            with open(target_path, "w", encoding="utf-8") as f:
                f.write(input_params.content)

            size_bytes = PathSecurity.validate_file_size(target_path)
            file_hash = PathSecurity.compute_sha256(target_path)
            file_id = _record_file_in_db(safe_name, target_path, "txt", "text/plain", context)

            return ToolResult(
                success=True,
                data={
                    "filename": safe_name,
                    "file_path": str(target_path),
                    "file_size_bytes": size_bytes,
                    "sha256": file_hash,
                    "file_id": file_id,
                },
                metadata={"file_type": "txt", "file_id": file_id},
            )
        except Exception as exc:
            return ToolResult(success=False, error=f"TXT Generation failed: {str(exc)}")


# --- 4. Excel Generation Tool ---

class CreateExcelInput(BaseModel):
    filename: str = Field(description="Target Excel filename (.xlsx)")
    headers: List[str] = Field(description="List of column headers")
    rows: List[List[Any]] = Field(description="Rows of spreadsheet records")
    sheet_name: Optional[str] = Field(default="Data", description="Sheet name")


class CreateExcelTool(BaseTool):
    tool_id = "create_excel"
    name = "Create Excel Spreadsheet"
    description = "Creates an Excel spreadsheet (.xlsx) with styled header rows and data tables."
    input_schema = CreateExcelInput
    risk_level = RiskLevel.LOW_RISK
    timeout_seconds = 30

    async def run(self, input_params: CreateExcelInput, context: Optional[Dict[str, Any]] = None) -> ToolResult:
        try:
            import openpyxl
            from openpyxl.styles import Font, PatternFill, Alignment

            base_name = input_params.filename
            if not base_name.endswith(".xlsx"):
                base_name += ".xlsx"

            safe_name = sanitize_filename(base_name)
            target_path = PathSecurity.resolve_safe_path(safe_name)

            wb = openpyxl.Workbook()
            ws = wb.active
            ws.title = input_params.sheet_name or "Data"

            # Header style
            header_font = Font(name="Calibri", size=11, bold=True, color="FFFFFF")
            header_fill = PatternFill(start_color="1A365D", end_color="1A365D", fill_type="solid")

            ws.append(input_params.headers)
            for col_idx in range(1, len(input_params.headers) + 1):
                cell = ws.cell(row=1, column=col_idx)
                cell.font = header_font
                cell.fill = header_fill
                cell.alignment = Alignment(horizontal="center")

            for r in input_params.rows:
                ws.append(r)

            # Auto-adjust column width
            for col in ws.columns:
                max_len = max(len(str(cell.value or "")) for cell in col)
                col_letter = openpyxl.utils.get_column_letter(col[0].column)
                ws.column_dimensions[col_letter].width = max(max_len + 3, 12)

            wb.save(str(target_path))

            size_bytes = PathSecurity.validate_file_size(target_path)
            file_hash = PathSecurity.compute_sha256(target_path)
            file_id = _record_file_in_db(
                safe_name,
                target_path,
                "xlsx",
                "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                context,
            )

            return ToolResult(
                success=True,
                data={
                    "filename": safe_name,
                    "file_path": str(target_path),
                    "file_size_bytes": size_bytes,
                    "sha256": file_hash,
                    "file_id": file_id,
                },
                metadata={"file_type": "xlsx", "file_id": file_id},
            )
        except Exception as exc:
            return ToolResult(success=False, error=f"Excel generation failed: {str(exc)}")

